import{_ as e}from"./chunks/img.Dck1PxLc.js";import{_ as r,C as i,c as t,o as n,j as a,G as l,a0 as o,a as d}from"./chunks/framework.DKRgXLPU.js";const s=JSON.parse('{"title":"Om Petanque Academy","description":"","frontmatter":{},"headers":[],"relativePath":"da/about.md","filePath":"da/about.md"}');const g=r({name:"da/about.md"},[["render",function(r,s,g,k,m,p){const u=i("AdBanner"),h=i("AdInArticle");return n(),t("div",null,[s[0]||(s[0]=a("h1",{id:"om-petanque-academy",tabindex:"-1"},[d("Om Petanque Academy "),a("a",{class:"header-anchor",href:"#om-petanque-academy","aria-label":'Permalink to "Om Petanque Academy"'},"​")],-1)),l(u),s[1]||(s[1]=o('<h2 id="en-passion-for-petanque" tabindex="-1">En passion for petanque <a class="header-anchor" href="#en-passion-for-petanque" aria-label="Permalink to &quot;En passion for petanque&quot;">​</a></h2><p>Velkommen til Pétanque Academy, hvor en dybtliggende passion for petanque har været en drivkraft i over 45 år. Min rejse med denne sport har været præget af dedikation, dygtighed og vedvarende entusiasme.</p><p>Petanque er ikke bare et spil; det er en måde at skabe kontakt, strategisk planlægning og nyde naturen på, og jeg har været så heldig at opleve dets mange facetter i næsten et halvt århundrede. Uanset om det er den præcise placering af en boule eller kammeratskabet i terrænet, er mit engagement i petanque stadig lige så stærkt som altid.</p><p><img src="'+e+'" alt="Patrik Wiik with friends"></p><p><em>At dele denne passion med venner er i sandhed det, der gør petanque så specielt. De utallige timer brugt på banen, fyldt med latter, venskabelig konkurrence og fælles historier, skaber bånd, der varer hele livet.</em></p><hr><h2 id="min-mission" tabindex="-1">Min mission <a class="header-anchor" href="#min-mission" aria-label="Permalink to &quot;Min mission&quot;">​</a></h2><p>Pétanque Academys mission er at hjælpe elitespillere med at frigøre deres fulde potentiale ved at fokusere på det mentale spil - det ofte oversete aspekt, der adskiller gode spillere fra store spillere.</p><p>Gennem denne hjemmeside deler jeg:</p><ul><li><strong>Mentale spilrammer</strong> udviklet baseret på årtiers erfaring</li><li><strong>Praktiske værktøjer og skabeloner</strong> til målsætning og træning</li><li><strong>Workshop-metoder</strong> til opbygning af psykologisk tryghed</li><li><strong>Evidensbaserede tilgange</strong> til præstation under pres</li></ul><p>Det handler ikke om teknisk coaching – det handler om at skabe det mentale fundament, der gør det muligt for dine tekniske færdigheder at skinne, når det betyder mest.</p><hr><h2 id="hvorfor-jeg-oprettede-denne-hjemmeside" tabindex="-1">Hvorfor jeg oprettede denne hjemmeside <a class="header-anchor" href="#hvorfor-jeg-oprettede-denne-hjemmeside" aria-label="Permalink to &quot;Hvorfor jeg oprettede denne hjemmeside&quot;">​</a></h2><p>Efter mere end 45 år i petanque har jeg set utallige talentfulde spillere kæmpe ikke med teknik, men med:</p><ul><li><strong>Indre kritiker</strong>, der ødelægger selvtilliden efter fejltagelser</li><li><strong>Pres</strong>, der får dem til at spille anderledes i konkurrencer</li><li><strong>Mangel på struktur</strong> i mental træning</li><li><strong>Isolation</strong> i deres udviklingsrejse</li></ul><p>Dette websted eksisterer for at ændre det. Alt indhold her er designet til at være øjeblikkeligt praktisk - skabeloner, du kan kopiere, frameworks, du kan anvende i dag, og værktøjer, der fungerer i reel konkurrence.</p><hr>',17)),l(h),s[2]||(s[2]=o('<h2 id="kontakt-os" tabindex="-1">Kontakt os <a class="header-anchor" href="#kontakt-os" aria-label="Permalink to &quot;Kontakt os&quot;">​</a></h2><p>Jeg vil meget gerne høre fra dig! Uanset om du har spørgsmål, ønsker at dele dine erfaringer eller er interesseret i workshops og træning, er du velkommen til at kontakte mig.</p><h3 id="kontaktoplysninger" tabindex="-1">Kontaktoplysninger <a class="header-anchor" href="#kontaktoplysninger" aria-label="Permalink to &quot;Kontaktoplysninger&quot;">​</a></h3><p><strong>E-mail:</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Facebook:</strong> <a href="https://www.facebook.com/patrik.wiik" target="_blank" rel="noreferrer">facebook.com/patrik.wiik</a></p><hr><h2 id="hjælp-mig-med-at-forbedre-denne-hjemmeside" tabindex="-1">Hjælp mig med at forbedre denne hjemmeside <a class="header-anchor" href="#hjælp-mig-med-at-forbedre-denne-hjemmeside" aria-label="Permalink to &quot;Hjælp mig med at forbedre denne hjemmeside&quot;">​</a></h2><p>Din feedback er uvurderlig! Denne side udvikler sig konstant baseret på, hvad elitespillere rent faktisk har brug for.</p><h3 id="jeg-vil-meget-gerne-høre-fra-dig-om" tabindex="-1">Jeg vil meget gerne høre fra dig om: <a class="header-anchor" href="#jeg-vil-meget-gerne-høre-fra-dig-om" aria-label="Permalink to &quot;Jeg vil meget gerne høre fra dig om:&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Hvad ville hjælpe dig mest?</p><ul><li><p><strong>Hvilket indhold vil du gerne se mere af?</strong></p><ul><li>Flere mentale spilteknikker?</li><li>Flere praktiske skabeloner?</li><li>Casestudier fra elitespillere?</li></ul></li><li><p><strong>Hvad mangler der på siden?</strong></p><ul><li>Emner der ikke er dækket?</li><li>Værktøjer du ville ønske eksisterede?</li><li>Ressourcer du ikke kan finde?</li></ul></li><li><p><strong>Hvad fungerer godt?</strong></p><ul><li>Hvilke sider har været mest nyttige?</li><li>Hvilke værktøjer har du rent faktisk brugt?</li><li>Hvad gjorde den største forskel for dig?</li></ul></li><li><p><strong>Hvordan kan jeg gøre det bedre?</strong></p><ul><li>Forbedringer af navigationen?</li><li>Indholdsorganisering?</li><li>Flere eksempler?</li><li>Forskellige formater?</li></ul></li></ul></div><h3 id="send-mig-din-feedback" tabindex="-1">Send mig din feedback <a class="header-anchor" href="#send-mig-din-feedback" aria-label="Permalink to &quot;Send mig din feedback&quot;">​</a></h3><p><strong>Send dine tanker til:</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Forslag til emnelinjer:</strong></p><ul><li>&quot;Feedback fra webstedet: [Dit emne]&quot;</li><li>&quot;Indholdsanmodning: [Hvad du har brug for]&quot;</li><li>&quot;Succeshistorie: [Hvordan den hjalp]&quot;</li><li>&quot;Forslag: [Din idé]&quot;</li></ul><p><strong>Hvad skal inkluderes:</strong></p><ul><li>Dit nuværende niveau/erfaring</li><li>Hvad du arbejder på</li><li>Specifik feedback eller anmodninger</li><li>Eventuelle succeshistorier med brug af indholdet</li></ul><hr><h2 id="hvad-andre-siger" tabindex="-1">Hvad andre siger <a class="header-anchor" href="#hvad-andre-siger" aria-label="Permalink to &quot;Hvad andre siger&quot;">​</a></h2><details class="details custom-block"><summary>Feedback fra elitespillere</summary><p><em>&quot;Det mentale spilindhold har fuldstændig ændret min tilgang til konkurrence. Alene Inner Coach-rammeværket var værd at finde denne hjemmeside.&quot;</em> — Regionalmester, Frankrig</p><p><em>&quot;Endelig er der en, der forstår teknikken, som ikke er problemet. Workshop-metoden gav vores klub en helt ny måde at træne på.&quot;</em> — Landsholdsspiller, Sverige</p><p><em>&quot;Målskabelonen og dagbogsskabelonen er præcis, hvad jeg havde brug for. Enkle, praktiske og faktisk brugbare.&quot;</em> — Turneringsspiller, Spanien</p></details><hr><h2 id="om-indholdet" tabindex="-1">Om indholdet <a class="header-anchor" href="#om-indholdet" aria-label="Permalink to &quot;Om indholdet&quot;">​</a></h2><p>Alt indhold på denne hjemmeside er:</p><ul><li><strong>Gratis og tilgængelig</strong> - Ingen betalingsmure, intet skjult indhold</li><li><strong>Praktisk og brugbar</strong> - Skabeloner du kan bruge i dag</li><li><strong>Evidensbaseret</strong> - Bygget på psykologisk forskning og mere end 45 års erfaring</li><li><strong>Opdateres løbende</strong> - Nyt indhold tilføjet baseret på din feedback</li></ul><hr><h2 id="privatliv-og-cookies" tabindex="-1">Privatliv og cookies <a class="header-anchor" href="#privatliv-og-cookies" aria-label="Permalink to &quot;Privatliv og cookies&quot;">​</a></h2><p>Dette websted bruger Google AdSense til at understøtte driften. Ved at bruge dette websted accepterer du Googles brug af cookies til annoncetilpasning og analyse.</p><p><strong>Vi respekterer dit privatliv:</strong></p><ul><li>Der indsamles ingen personlige data ud over standardanalyser</li><li>Ingen e-maillister eller spam</li><li>Kontaktoplysninger bruges kun til at besvare dine beskeder</li></ul><hr><h2 id="forbind-og-del" tabindex="-1">Forbind og del <a class="header-anchor" href="#forbind-og-del" aria-label="Permalink to &quot;Forbind og del&quot;">​</a></h2><p>Hvis du finder dette indhold værdifuldt:</p><ul><li><strong>Del det</strong> med dine træningspartnere</li><li><strong>Anbefal det</strong> til din klub</li><li><strong>Link til det</strong> fra dine egne ressourcer</li><li><strong>Giv feedback</strong> for at forbedre det</li></ul><p>Sammen kan vi løfte det mentale petanque-spil verden over.</p><hr>',34)),l(u),s[3]||(s[3]=a("p",null,[a("strong",null,"Tak fordi du er en del af Pétanque Academy!")],-1)),s[4]||(s[4]=a("p",null,[a("em",null,"— Patrik Wiik")],-1))])}]]);export{s as __pageData,g as default};
